<?php namespace App\Controllers\Api; use CodeIgniter\RESTful\ResourceController; class Debug extends ResourceController { public function checkDistance() { $db = \Config\Database::connect(); $pickupLat = -3.40848290; $pickupLng = 119.31244610; $builder = $db->table("drivers"); $builder->select("id, name, vehicle_type, latitude, longitude, last_heartbeat_at, ( 6371 * acos( LEAST(1.0, cos(radians(" . $pickupLat . ")) * cos(radians(latitude)) * cos(radians(longitude) - radians(" . $pickupLng . ")) + sin(radians(" . $pickupLat . ")) * sin(radians(latitude))) ) ) AS distance"); $builder->orderBy("distance", "ASC"); $results = $builder->get()->getResult(); $html = "<h3>Jarak Driver ke Titik Alun-Alun (-3.4084, 119.3124):</h3><table border=\"1\" cellpadding=\"5\" style=\"border-collapse:collapse;\"><tr><th>ID</th><th>Nama</th><th>Tipe</th><th>Jarak (KM)</th><th>Status</th><th>Lat, Lng</th><th>Heartbeat</th></tr>"; foreach($results as $r) { $dist = round($r->distance, 2); $status = ($dist <= 3) ? "<span style=\"color:green\">MASUK RADIUS 3KM</span>" : (($dist <= 5) ? "<span style=\"color:orange\">MASUK 5KM, DITOLAK 3KM</span>" : "<span style=\"color:red\">TERLALU JAUH</span>"); $html .= "<tr><td>{$r->id}</td><td>{$r->name}</td><td>{$r->vehicle_type}</td><td><b>{$dist} KM</b></td><td>{$status}</td><td>{$r->latitude}, {$r->longitude}</td><td>{$r->last_heartbeat_at}</td></tr>"; } $html .= "</table><br><p>Catatan: Radius pencarian Anda diatur ke 3 KM. Jika jarak driver lebih dari 3 KM, mereka TIDAK AKAN menerima orderan!</p>"; return $this->response->setHTML($html); } }
